    font-family: "Noto Sans KR", sans-serif;
    margin: 0;
    padding: 0;
}

.filter-containers {
    padding: 20px;
    border: 1px solid #ddd;
    border-radius: 3px;
    background: linear-gradient(0deg, rgb(246 246 246) 0%, rgba(255, 255, 255, 1) 100%);
    align-items: start;
    /* Align items at the start vertically */
    margin-bottom: 40px;
    margin-top: 30px;
}

.filter-container {
    display: grid;
    grid-template-columns: 3fr 0fr;
    /* Left side with filter items, right side with button */
    margin-bottom: 30px;
}

.filter-items {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    /* 3 columns for filter items */
    gap: 20px 3%;
}

.filter-item {
    display: flex;
    align-items: center;
    gap: 5px;
    /* Reduced space between label and input */
}

.filter-item label {
    width: 25%;
    font-weight: bold;
    font-size: 14px;
    color: #333;
}

.filter-item input {
    flex: 1;
    padding: 8px;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 14px;
    box-sizing: border-box;
}

.button-container {
    display: flex;
    align-items: center;
    /* 세로(위아래) 가운데 정렬 */
    justify-content: flex-end;
    /* 가로 가운데 정렬 (필요 시) */
}

.search-btn {
    padding: 10px 20px;
    background-color: #004e90;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 14px;
    width: 3%;
    text-align: center;
    display: flex;
    align-items: center;
    /* 세로(위아래) 가운데 정렬 */
    justify-content: center;
    /* 가로 가운데 정렬 */
}

.search-btn .bi {
    text-align: center;
    display: block;
}

.reset-btn {
    padding: 10px 20px;
    background-color: #bbb;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 14px;
    width: 3%;
    text-align: center;
    display: flex;
    align-items: center;
    /* 세로(위아래) 가운데 정렬 */
    justify-content: center;
    /* 가로 가운데 정렬 */
    margin-right: 5px;
}

.reset-btn:hover {
    background-color: #ccc;
}

.reset-btn .bi {
    text-align: center;
    display: block;
}

.filter-item select {
    width: 80%;
    height: 34px;
    border: 1px solid #ccc;
    border-radius: 4px;
    margin-left: 5px;
}


.search-btn:hover {
    background-color: #0056b3;
}

/* styles.css */

.btn-common {
    padding: 6px 12px;
    border: 1px solid #004e90;
    background-color: #004e90;
    color: white;
    font-size: 14px;
    border-radius: 3px;
    cursor: pointer;
}

.btn-common:hover {
    background-color: #0056b3;
}

.add {
    float: right;
    margin-bottom: 10px;
}

.delete-btn {
    position: absolute;
    top: -45px;
}


.modal {
    overflow: auto;
    display: none;
    /* 모달을 띄우기 위해 사용 (숨길 때는 'none') */
    position: fixed;
    top: 0px;
    left: 0;
    width: 100%;
    height: 100%;
    background-color: rgba(0, 0, 0, 0.5);
    justify-content: center;
    align-items: center;
}

.modal-content {
    top: 50px;
    background-color: white;
    padding: 20px;
    margin: 0 auto;
    width: 50%;
    border-radius: 3px;
    position: relative;
}

.close-btn2 {
    position: absolute;
    top: 10px;
    right: 15px;
    font-size: 24px;
    cursor: pointer;
}

.order-main-box {
    margin: 40px;
}

.main-name1 {
    font-size: 30px;
    font-weight: bold;
    margin-bottom: 40px;
}


h2 {
    margin-top: 0;
    text-align: center;
}

.store-form {
    display: flex;
    flex-direction: column;
    gap: 15px;
}

.form-group {
    display: flex;
    flex-direction: column;
}

.form-group label {
    font-weight: bold;
}

.form-row {
    display: flex;
    gap: 15px;
}

input {
    padding: 10px;
    border: 1px solid #ddd;
    border-radius: 2px;
    font-size: 14px;
}

.map img {
    width: 70%;
    margin: auto;
    border: 1px solid #ddd;
    border-radius: 2px;
}

.form-actions {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
}

.submit-btn,
.cancel-btn,
.cancel-btn2,
.cancel-btn3 {
    padding: 10px 20px;
    font-size: 14px;
    cursor: pointer;
    border: none;
    border-radius: 2px;
}

.submit-btn {
    background-color: #0056b3;
    color: white;
}

.cancel-btn,
.cancel-btn2 {
    background-color: #ddd;
}

.search-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.8rem;
    margin-top: 100px;
    position: relative;
}

.search-table,
th,
td {
    border: 1px solid #ddd;
}

.search-table th {
    border-top: 2px solid #0063ac;
    text-align: center;
}

.search-table tr:hover {
    background-color: rgba(200, 230, 255, 0.366);
}

.search-table tbody tr:last-child {
    font-weight: bold;
    /* Apply bold styling */
    background: rgb(241, 241, 241);
    background: linear-gradient(1deg, rgba(241, 241, 241, 1) 0%, rgba(255, 255, 255, 1) 100%);
}

.search-table tbody tr:last-child td {
    text-align: center;
}

.search-table tbody td i {
    float: right;
    cursor: pointer;
}

tr:nth-child(0) {
    font-weight: bold;
}

/* tr:nth-last-child(1) {
  font-weight: bold;
  background-color: #f4f4f4;
} */

.search-table th,
td {
    padding: 10px;
    text-align: left;

}

.search-table th {
    background: rgb(241, 241, 241);
    background: linear-gradient(1deg, rgba(241, 241, 241, 1) 0%, rgba(255, 255, 255, 1) 100%);

}

.search-table th:nth-child(1),
.search-table th:nth-child(2),
.search-table td:nth-child(3),
.search-table td:nth-child(1) {
    text-align: center;
}

.pageHeader {
    margin-bottom: 60px;
}

.pageHeader .bi {
    margin-right: 10px;
}

/* .search-button {
    position: absolute;
    right: 5px;
    cursor: pointer;
    background: none;
    border: none;
    font-size: 14px;
} */

.breadcrumb {
    display: flex;
    align-items: center;
    font-size: 15px;
    color: #555;
    margin-bottom: 30px;
}

.breadcrumb a {
    text-decoration: none;
    color: #555;
    margin: 0 5px;
    display: flex;
    align-items: center;
}

.breadcrumb a:hover {
    color: #007bff;
}

.breadcrumb .separator {
    margin: 0 5px;
    color: #ccc;
}

.breadcrumb .home-icon {
    width: 16px;
    height: 16px;

    background-size: contain;
    display: inline-block;
    margin-right: 5px;
}


.selected-row {
    background-color: rgba(200, 230, 255, 0.366);
}


/*  sort */
.sortBtn {
    border: 1px solid #d0d0d0;
    margin-left: 10px;
    color: #4c4c4c;
    font-size: 15px;
    width: 22px;
    height: 20px;
    text-align: center;
    padding: 0px;
    float: right;
}


.chart-container {
    margin: 0 auto;
    position: relative;
    height: 30%;
    width: 50%;
    padding: 20px;
    align-items: center;
    text-align: center;
}

.chart-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
}

.chart-header h3 {
    margin: 0;
    color: #333;
}

.chart-header button {
    background-color: #0056b3;
    border: none;
    color: white;
    padding: 8px 16px;
    border-radius: 5px;
    cursor: pointer;
    transition: background-color 0.3s;
}

.chart-header button:hover {
    background-color: #004494;
}

.canvas {
    background: white;
    width: 100%;
    height: 100%;
    align-items: center;
}



/* 페이지네이션 */

.pagination {
    margin-top: 2rem;
    width: 100%;
    display: flex;
    justify-content: center;
    gap: 1rem;
    cursor: pointer;
}

/* .pagination_link {
    transition: all 0.25s;
    padding: 0.2rem 0.6rem;
    border-radius: 0.3rem;
} */



.pagination_link_active {
    background-color: #bbb;
    color: #fefefe;
}

.pagination_link.disabled {
    color: #ccc;
    /* 비활성화 시 색상 */
    cursor: not-allowed;
    /* 비활성화 시 커서 스타일 */
}


.pagination_link {
    /* transition: all 0.25s; */
    padding: 0.2rem 0.6rem;
    border-radius: 0.3rem;
    outline: none;
    /* 기본 테두리 제거 */
    user-select: none;
    /* 텍스트 선택 방지 */
}

.pagination_link:focus {
    outline: none;
    /* 포커스 시 테두리 제거 */
    box-shadow: none;
    /* 박스 그림자 제거 */
}

.pagination_link:hover {
    background-color: #ddd;
    /* 호버 시 배경색 변경 */
}

.bi-emoji-tear {
    margin: 0 0 2px 2px;
}

