___CSS_LOADER_EXPORT___.push([module.id, `.address-input-container {
  padding: 20px;
  background-color: #f9f9f9;
  border-radius: 5px;
  box-shadow: 0px 2px 10px rgba(0, 0, 0, 0.1);
  width: 412px;
  margin: 0 auto;
}

.address-input-header {
  font-size: 24px;
  font-weight: bold;
  margin-bottom: 20px;
  text-align: center;
}

.address-input-zipcode-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 15px;
}

.address-input-zipcode {
  font-size: 16px;
  font-weight: bold;
}

/* 주소찾기 버튼 */
.address-input-search-button {
  padding: 8px 16px;
  background-color:#004e90;
  color: white;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  font-size: 14px;
}

.address-input-search-button:hover {
  background-color: #0056b3;
}

/* 주소찾기 클릭했을 때 나오는 컨테이너 */
.address-input-postcode-container {
  margin-top: 15px;
  background-color: #fff;
  padding: 5px;
  border: 1px solid #ddd;
  border-radius: 5px;
  box-shadow: 0px 2px 10px rgba(0, 0, 0, 0.1);
}

/* 찾은 주소 입력되는 컨테이너 */
.address-input-address-container {
  margin-bottom: 15px;
  font-size: 16px;
  background-color: #fff;
  border: 1px solid #ddd;
  padding: 10px;
  border-radius: 5px;
}

/* 찾은 주소 입력되는 컨테이너 */
.address-input-detailed-container {
  margin-top: 10px;
}

/* 상세주소 입력란 */
.address-input-detailed-input {
  width: 94%;
  padding: 10px;
  border: 1px solid #ddd;
  border-radius: 5px;
  font-size: 14px;
}

/* 확인 버튼 */
.address-input-confirm-button {
  display: block;
  width: 100%;
  padding: 10px;
  background-color: #004e90;
  color: white;
  border: none;
  border-radius: 5%;
  cursor: pointer;
  font-size: 16px;
  margin-top: 20px;
}

.address-input-confirm-button:hover {
  background-color: #0056b3;
}


